def add(y,n,r,t,tags,s,sol,reason,notes=''):
 src=f'https://www.ommenlinea.org/wp-content/uploads/concursos/nacionales/nac{y-1986}.pdf';su=f'https://www.ommenlinea.org/wp-content/uploads/{y+1}/03/Tzaloa-1-{y+1}.pdf'
